import ChildComponent from './ChildComponent.vue'

const data = ref(null)
const loading = ref(true)
const error = ref(null)

onMounted(async () => {
  try {
    const response = await fetch('https://api.example.com/data')
    const result = await response.json()
    data.value = result
  } catch (err) {
    error.value = err.message
  } finally {
    loading.value = false
  }
})
</script>

<template>
  <div>
    <div v-if="loading">Loading...</div>
    <div v-else-if="error">Error: {{ error }}</div>
    <ChildComponent v-else :data="data" />
  </div>
</template>
```

## Child Component (ChildComponent.vue)

```vue
<script setup>
defineProps({
  data: {
    type: Object,
    required: true
  }
})
</script>

<template>
  <div>
    <h2>{{ data.title }}</h2>
    <p>{{ data.description }}</p>
  </div>
</template>
```

## Key Points

- **`v-else`** ensures the child component only renders when data is available
- **`ref(null)`** initializes the data as null, so the child won't receive undefined props
- **`defineProps`** in the child declares what props it expects
- The child component is **not rendered** until the API call completes successfully

